import { arrayMapPush } from './collection';

/**
 * Utilities to update JSON documents while preserving the structure of an existing document as much as possible.
 *
 * Merging an updated JSON value into an existing JSON value keeps the property order and array element order
 * of the existing document and only applies the actual differences; new properties and elements are inserted
 * at the position they have in the updated value relative to their neighbours. This keeps diffs minimal when a
 * JSON file is regenerated by a tool that does not guarantee a stable property or element order.
 */

export type JsonChangeType = 'added' | 'removed' | 'changed' | 'reordered';

export interface JsonChange {
    /**
     * Path of the changed value, for example `Items[2].Name`; paths of removed values point into the existing
     * document, all other paths point into the merged document.
     */
    readonly path: string;
    readonly type: JsonChangeType;
}

export interface StableJsonMergeOptions {
    /**
     * Returns a key that identifies an array element across versions of a document, for example a
     * record source key. Elements with the same identity are merged instead of being replaced.
     */
    identity?: (element: unknown, path: string) => string | undefined;
    /**
     * Decides if the element order of the existing array is kept. When the order is not kept the
     * order of the updated array is used and a `reordered` change is reported when it differs.
     * Defaults to keeping the existing order for arrays that only contain objects (records), as their
     * order usually carries no meaning; arrays of primitives follow the updated order.
     */
    preserveArrayOrder?: (existing: unknown[], updated: unknown[], path: string) => boolean;
    /**
     * Minimum similarity (0-1) for pairing array records that are not equal and have no matching identity;
     * similarity is the share of equal properties of two objects, or equal elements of two arrays, relative to
     * the larger of both. Paired records are merged in place, unpaired records are replaced.
     * Defaults to `0.5`; `false` disables similarity matching.
     */
    similarity?: number | false;
}

export interface StableJsonMergeResult<T = unknown> {
    /** The merged value; structurally equal to the updated value, ordered like the existing value */
    readonly value: T;
    /** List of changes between the existing and the updated value */
    readonly changes: JsonChange[];
}

export interface StableJsonUpdateResult extends StableJsonMergeResult {
    /** JSON text to write; equals the existing text when there are no changes */
    readonly text: string;
    /** `true` when the text of the document changed */
    readonly changed: boolean;
}

/**
 * Merge an updated JSON value into an existing JSON value, keeping the property and element order of the
 * existing value. The returned value is structurally equal to `updated`.
 * @param existing Existing JSON value
 * @param updated Updated JSON value
 * @param options Merge options
 */
export function mergeJsonStable<T>(existing: unknown, updated: T, options?: StableJsonMergeOptions): StableJsonMergeResult<T> {
    const changes: JsonChange[] = [];
    const value = new StableJsonMerger(options ?? {}, changes).merge(existing, updated, '');
    return { value: value as T, changes };
}

/**
 * Update the text of an existing JSON document with an updated JSON value. When the documents are equal,
 * ignoring property and record order, the existing text is returned unchanged; otherwise the merged value
 * is serialized using the indentation, line endings and trailing newline of the existing text.
 *
 * When there is no existing text, or one of both documents is not valid JSON, the documents cannot be merged:
 * the updated text is returned as is and no changes are listed.
 * @param existingText Text of the existing document or `undefined` when there is no existing document
 * @param updatedText Text of the updated document
 * @param options Merge options
 */
export function updateJsonText(existingText: string | undefined, updatedText: string, options?: StableJsonMergeOptions): StableJsonUpdateResult {
    const existing = existingText === undefined ? undefined : tryParseJson(existingText);
    const updated = tryParseJson(updatedText);
    if (existingText === undefined || !existing || !updated) {
        return { text: updatedText, value: updated?.value, changed: existingText !== updatedText, changes: [] };
    }

    const result = mergeJsonStable(existing.value, updated.value, options);
    if (!result.changes.length) {
        return { ...result, text: existingText, changed: false };
    }
    return { ...result, text: formatJsonLike(existingText, result.value), changed: true };
}

/**
 * Serialize a value as JSON using the byte order mark, indentation, line endings and trailing newline of a
 * reference JSON text.
 * @param reference JSON text whose formatting is reused
 * @param value Value to serialize
 */
export function formatJsonLike(reference: string, value: unknown): string {
    const bom = reference.startsWith('﻿') ? '﻿' : '';
    const eol = reference.includes('\r\n') ? '\r\n' : '\n';
    const trailingNewline = /\r?\n$/.test(reference) ? eol : '';
    const text = JSON.stringify(value, undefined, detectIndent(reference));
    return bom + (eol === '\n' ? text : text.replaceAll('\n', eol)) + trailingNewline;
}

const defaultIndent = 4;

/**
 * Indentation of a JSON text: the indentation of the first indented line, none for single-line JSON
 * or the default indentation when no line is indented (e.g. an empty object).
 */
function detectIndent(text: string): string | number {
    const indentation = /^[ \t]+(?=\S)/m.exec(text);
    if (indentation) {
        return indentation[0];
    }
    const content = text.trim();
    const isEmptyContainer = /^[[{]\s*[\]}]$/.test(content);
    return content.includes('\n') || isEmptyContainer ? defaultIndent : 0;
}

function tryParseJson(text: string): { value: unknown } | undefined {
    try {
        return { value: JSON.parse(text.startsWith('﻿') ? text.slice(1) : text) };
    } catch {
        return undefined;
    }
}

type JsonObject = Record<string, unknown>;

function isJsonObject(value: unknown): value is JsonObject {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function valueKind(value: unknown): string {
    return Array.isArray(value) ? 'array' : value === null ? 'null' : typeof value;
}

function joinPath(path: string, key: string | number): string {
    if (typeof key === 'number') {
        return `${path}[${key}]`;
    }
    return path ? `${path}.${key}` : key;
}

const canonicalCache = new WeakMap<object, string>();

/**
 * JSON text of a value with sorted object keys, so values that only differ in key order have the same text.
 * Cached per object, so nested values are serialized once while merging a document.
 */
function canonicalJson(value: unknown): string {
    if (typeof value !== 'object' || value === null) {
        return JSON.stringify(value);
    }
    let text = canonicalCache.get(value);
    if (text === undefined) {
        text = Array.isArray(value)
            ? `[${value.map(canonicalJson).join(',')}]`
            : `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonicalJson((value as JsonObject)[key])}`).join(',')}}`;
        canonicalCache.set(value, text);
    }
    return text;
}

interface Fingerprint {
    /** Canonical property (`key:value`) or element mapped to its number of occurrences */
    readonly entries: Map<string, number>;
    readonly size: number;
}

const fingerprintCache = new WeakMap<object, Fingerprint>();

/**
 * Fingerprint of a record (object or array) used to calculate the similarity of two records.
 */
function fingerprint(record: object): Fingerprint {
    let result = fingerprintCache.get(record);
    if (!result) {
        const entries = new Map<string, number>();
        const items = Array.isArray(record)
            ? record.map(canonicalJson)
            : Object.entries(record).map(([key, value]) => `${JSON.stringify(key)}:${canonicalJson(value)}`);
        for (const item of items) {
            entries.set(item, (entries.get(item) ?? 0) + 1);
        }
        result = { entries, size: items.length };
        fingerprintCache.set(record, result);
    }
    return result;
}

/**
 * Similarity of two records: the number of equal properties or elements relative to the larger record.
 */
function similarity(a: object, b: object): number {
    const fingerprintA = fingerprint(a);
    const fingerprintB = fingerprint(b);
    const size = Math.max(fingerprintA.size, fingerprintB.size);
    if (size === 0) {
        return 1;
    }
    let equal = 0;
    for (const [entry, count] of fingerprintA.entries) {
        equal += Math.min(count, fingerprintB.entries.get(entry) ?? 0);
    }
    return equal / size;
}

/**
 * Insert new items into an ordered list after the closest item that precedes them in `order`, or at the
 * start of the list when no preceding item is in the list.
 */
function insertOrdered<K>(list: K[], order: readonly K[], isNew: (item: K) => boolean): K[] {
    for (const [index, item] of order.entries()) {
        if (!isNew(item)) {
            continue;
        }
        let anchor = -1;
        for (let previous = index - 1; previous >= 0 && anchor === -1; previous--) {
            anchor = list.indexOf(order[previous]);
        }
        list.splice(anchor + 1, 0, item);
    }
    return list;
}

/** Upper bound for pairwise record comparisons in a single array to keep merging large arrays fast. */
const maxSimilarityComparisons = 250_000;

class StableJsonMerger {

    constructor(
        private readonly options: StableJsonMergeOptions,
        private readonly changes: JsonChange[]
    ) {
    }

    public merge(existing: unknown, updated: unknown, path: string): unknown {
        if (canonicalJson(existing) === canonicalJson(updated)) {
            return existing;
        }
        if (isJsonObject(existing) && isJsonObject(updated)) {
            return this.mergeObject(existing, updated, path);
        }
        if (Array.isArray(existing) && Array.isArray(updated)) {
            return this.mergeArray(existing, updated, path);
        }
        this.changes.push({ path, type: 'changed' });
        return updated;
    }

    private mergeObject(existing: JsonObject, updated: JsonObject, path: string): JsonObject {
        const existingKeys = Object.keys(existing);
        const updatedKeys = Object.keys(updated);
        const removed = existingKeys.filter(key => !Object.hasOwn(updated, key));
        const added = new Set(updatedKeys.filter(key => !Object.hasOwn(existing, key)));

        this.changes.push(...removed.map(key => ({ path: joinPath(path, key), type: 'removed' as const })));
        this.changes.push(...[...added].map(key => ({ path: joinPath(path, key), type: 'added' as const })));

        const keys = insertOrdered(existingKeys.filter(key => Object.hasOwn(updated, key)), updatedKeys, key => added.has(key));
        return Object.fromEntries(keys.map(key => [
            key,
            added.has(key) ? updated[key] : this.merge(existing[key], updated[key], joinPath(path, key))
        ]));
    }

    private mergeArray(existing: unknown[], updated: unknown[], path: string): unknown[] {
        // Maps updated element index -> existing element index
        const matches = this.matchElements(existing, updated, path);
        const preserveOrder = this.options.preserveArrayOrder?.(existing, updated, path)
            ?? (existing.length > 0 && updated.length > 0 && [...existing, ...updated].every(isJsonObject));

        let order: number[];
        if (preserveOrder) {
            order = this.preservedOrder(existing, updated, matches);
        } else {
            order = [...updated.keys()];
            const existingOrder = order.map(index => matches.get(index)).filter(index => index !== undefined);
            if (existingOrder.some((index, i) => i > 0 && index < existingOrder[i - 1])) {
                this.changes.push({ path, type: 'reordered' });
            }
        }

        const matchedExisting = new Set(matches.values());
        for (const existingIndex of existing.keys()) {
            if (!matchedExisting.has(existingIndex)) {
                this.changes.push({ path: joinPath(path, existingIndex), type: 'removed' });
            }
        }

        return order.map((updatedIndex, resultIndex) => {
            const existingIndex = matches.get(updatedIndex);
            if (existingIndex === undefined) {
                this.changes.push({ path: joinPath(path, resultIndex), type: 'added' });
                return updated[updatedIndex];
            }
            return this.merge(existing[existingIndex], updated[updatedIndex], joinPath(path, resultIndex));
        });
    }

    /**
     * Pair updated elements with existing elements: first elements that are equal (ignoring key order), then
     * elements with the same identity and finally records that are similar enough.
     */
    private matchElements(existing: unknown[], updated: unknown[], path: string): Map<number, number> {
        const matches = new Map<number, number>();
        const unmatched = new Set(existing.keys());
        const identities = (elements: unknown[]) => elements.map((element, index) => this.options.identity?.(element, joinPath(path, index)));
        const existingIdentities = identities(existing);
        const updatedIdentities = identities(updated);

        this.pairByKey(existing.map(canonicalJson), updated.map(canonicalJson), matches, unmatched);
        this.pairByKey(existingIdentities, updatedIdentities, matches, unmatched);

        const threshold = this.options.similarity ?? 0.5;
        if (threshold !== false) {
            this.pairBySimilarity(existing, updated, matches, unmatched, {
                threshold,
                canPair: (existingIndex, updatedIndex) => existingIdentities[existingIndex] === undefined
                    || updatedIdentities[updatedIndex] === undefined
                    || existingIdentities[existingIndex] === updatedIdentities[updatedIndex]
            });
        }
        return matches;
    }

    /**
     * Pair unmatched elements that have the same key, in order of appearance.
     */
    private pairByKey(existingKeys: (string | undefined)[], updatedKeys: (string | undefined)[], matches: Map<number, number>, unmatched: Set<number>) {
        const candidates = new Map<string, number[]>();
        for (const index of unmatched) {
            const key = existingKeys[index];
            if (key !== undefined) {
                arrayMapPush(candidates, key, index);
            }
        }
        for (const [index, key] of updatedKeys.entries()) {
            const existingIndex = key === undefined || matches.has(index) ? undefined : candidates.get(key)?.shift();
            if (existingIndex !== undefined) {
                matches.set(index, existingIndex);
                unmatched.delete(existingIndex);
            }
        }
    }

    /**
     * Pair the remaining records (objects and arrays) that are similar enough, so a changed record without
     * identity is merged in place rather than replaced. Pairs are assigned most similar first, preferring the
     * closest position on equal similarity.
     */
    private pairBySimilarity(
        existing: unknown[],
        updated: unknown[],
        matches: Map<number, number>,
        unmatched: Set<number>,
        options: { threshold: number; canPair: (existingIndex: number, updatedIndex: number) => boolean }
    ) {
        const isRecord = (value: unknown): value is object => typeof value === 'object' && value !== null;
        const candidates = [...unmatched].filter(index => isRecord(existing[index]));
        const pending = [...updated.keys()].filter(index => !matches.has(index) && isRecord(updated[index]));
        if (candidates.length * pending.length > maxSimilarityComparisons) {
            return;
        }

        const pairs: { updatedIndex: number; existingIndex: number; score: number }[] = [];
        for (const updatedIndex of pending) {
            for (const existingIndex of candidates) {
                const existingRecord = existing[existingIndex] as object;
                const updatedRecord = updated[updatedIndex] as object;
                if (valueKind(existingRecord) !== valueKind(updatedRecord) || !options.canPair(existingIndex, updatedIndex)) {
                    continue;
                }
                const score = similarity(existingRecord, updatedRecord);
                if (score > 0 && score >= options.threshold) {
                    pairs.push({ updatedIndex, existingIndex, score });
                }
            }
        }

        pairs.sort((a, b) => b.score - a.score ||
            Math.abs(a.updatedIndex - a.existingIndex) - Math.abs(b.updatedIndex - b.existingIndex));
        for (const { updatedIndex, existingIndex } of pairs) {
            if (!matches.has(updatedIndex) && unmatched.has(existingIndex)) {
                matches.set(updatedIndex, existingIndex);
                unmatched.delete(existingIndex);
            }
        }
    }

    /**
     * Order the updated element indexes by the position of their matching existing element; new elements are
     * placed after the element that precedes them in the updated array.
     */
    private preservedOrder(existing: unknown[], updated: unknown[], matches: Map<number, number>): number[] {
        const byExisting = new Map([...matches].map(([updatedIndex, existingIndex]) => [existingIndex, updatedIndex]));
        const order = [...existing.keys()]
            .map(existingIndex => byExisting.get(existingIndex))
            .filter(index => index !== undefined);
        return insertOrdered(order, [...updated.keys()], index => !matches.has(index));
    }
}
